/* ── Design Tokens ─────────────────────────────────────────── */
:root {
  /* Dark forge identity (~70%) — charcoal + molten gold */
  --bg:     #0b0a08;
  --s1:     #141210;
  --s2:     #1c1915;
  --s3:     #26221c;
  --b1:     #3a342c;
  --b2:     #5c4f3d;
  --b3:     #8a7355;
  --t1:     #f5efe6;
  --t2:     #c9bdb0;
  --t3:     #95887a;
  --acc:    #e8a045;
  --acc-ink:#1a1208;
  --acc-dim:rgba(232,160,69,0.14);
  --acc-b:  rgba(232,160,69,0.30);
  --silver: #cfc7bc;
  --grn:    #14f1b2;
  --amb:    #fde68a;
  --red:    #ef4444;

  /* Paper relief (~30%) — warm ash daylight, forge-copper accent */
  --paper:         #d9d0c4;
  --paper-soft:    #ccc3b6;
  --paper-raised:  #e6dfd4;
  to { opacity: 1; transform: translateY(0); }
}

.float-anim {
  animation: float-soft 5.5s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  .float-anim { animation: none; }
}

/* ── Hero element styles ─────────────────────────────────────── */
.hero-line-overflow {
  overflow: hidden;
  line-height: 1;
  width: 100%;
  max-width: 100%;
}

.hero-h {
  --hero-scale: 1;

@keyframes ember-flicker {
  0%, 100% { filter: brightness(1); }
  35% { filter: brightness(1.45); }
  65% { filter: brightness(0.8); }
}

@media (prefers-reduced-motion: reduce) {
  .hero-ember { animation: none; opacity: 0; }
  .hero-forge-video { display: none !important; }
}

@media (max-width: 767px) {
  .hero-forge-video { display: none !important; }
}

/* ── Buttons ─────────────────────────────────────────────────── */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  background: var(--acc);
  color: var(--acc-ink);
  font-weight: 600;
  padding: 14px 30px;
  border-radius: 10px;
  font-size: 15px;
