  box-shadow: 0 14px 36px rgba(232,160,69,0.18);
  text-decoration: none;
}
.btn-primary svg { transition: transform 0.2s ease; }
.btn-primary:hover { opacity: 0.96; transform: translateY(-1px); box-shadow: 0 16px 40px rgba(232,160,69,0.24); }
.btn-primary:hover svg { transform: translateX(3px); }

.btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  background: rgba(255, 255, 255, 0.025);
  color: var(--t1);
  border: 1px solid color-mix(in srgb, var(--acc) 26%, var(--b2));
  font-weight: 600;
  padding: 14px 30px;
  border-radius: 10px;
  font-size: 15px;
  transition: border-color 0.2s, background-color 0.2s, color 0.2s, box-shadow 0.2s;
