@media (hover: none), (pointer: coarse), (max-width: 767px) {
  .btn-primary:hover, .card-lift:hover { transform: none; }
}

/* ── FAQ ─────────────────────────────────────────────────────── */
.faq-btn:hover { background: rgba(232,160,69,0.06); }

/* ── Focus visible (forge gold language; stronger than idle borders) ─ */
:focus-visible {
  outline: 2px solid rgba(232, 160, 69, 0.85);
