  border-radius: 6px;
}

/* Skip link uses CTA ink, never white on gold */
.skip-link:focus,
.skip-link:focus-visible {
  outline-offset: 2px;
}

/* Sticky-target friendly headings */
[id] {
  scroll-margin-top: var(--nav-offset);
}

/* ── Scrollbar ───────────────────────────────────────────────── */
::-webkit-scrollbar { width: 4px; height: 4px; }
::-webkit-scrollbar-track { background: var(--s1); }
