/* ── Reduced motion ──────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .btn-primary:hover,
  .card-lift:hover {
    transform: none;
  }

  html {
    scroll-behavior: auto;
  }
}

