import { ReactNode, useEffect } from "react"
import { usePathname } from "next/navigation"
import { Nav } from "@/components/Nav"
import { Footer } from "@/components/Footer"
import { trackExperienceEvent } from "@/lib/experience-analytics-client"
import { parseEnquiryIntent } from "@/lib/enquiry-intents"

interface SiteChromeProps {
  children: ReactNode
}

export function SiteChrome({ children }: SiteChromeProps) {
  const pathname = usePathname()
  const isInteractiveJourney = pathname === "/interactive"

  useEffect(() => {
    document.documentElement.dataset.scalesmithsHydrated = "true"
    return () => {
      delete document.documentElement.dataset.scalesmithsHydrated
    }
  }, [])

  useEffect(() => {
    function captureNavigation(event: MouseEvent) {
      const anchor = (event.target as Element | null)?.closest?.("a")
      const href = anchor?.getAttribute("href")
      if (!href) return
      if (href.startsWith("/quote")) {
        const intent = parseEnquiryIntent(new URL(href, window.location.origin).searchParams.get("intent"))
        trackExperienceEvent("quote_cta_clicked", { metadata: { source: `link:${pathname}`, target: href, intent } })
      }
      if (/^https?:\/\//.test(href) && !href.includes(window.location.hostname)) {
        trackExperienceEvent("navigation_exit", { metadata: { target: new URL(href).hostname } })
      }
    }

    document.addEventListener("click", captureNavigation, { capture: true })
    return () => document.removeEventListener("click", captureNavigation, { capture: true })
  }, [pathname])

  return (
    <>
      <a href="#main" className="skip-link sr-only focus:not-sr-only focus:absolute focus:left-4 focus:top-4 focus:z-50 focus:rounded-md focus:bg-acc focus:px-4 focus:py-2 focus:font-semibold focus:text-acc-ink">
        Skip to content
      </a>
      {!isInteractiveJourney && <Nav />}
      <main id="main" tabIndex={-1}>{children}</main>
      {!isInteractiveJourney && <Footer />}
    </>
  )
}
