import { createElement } from "react"
import { renderToStaticMarkup } from "react-dom/server"
import { describe, expect, it, vi } from "vitest"

vi.mock("@sentry/nextjs", () => ({ captureException: vi.fn() }))
vi.mock("next/link", () => ({
  default: ({ href, children, prefetch: _prefetch, ...rest }: { href: string; children: unknown; prefetch?: boolean }) =>
    createElement("a", { href, ...rest }, children as never),
}))

import RouteError from "./error"

describe("web route error page", () => {
  it("offers retry and real routes without leaking the error message", () => {
    const error = Object.assign(new Error("private stack detail"), { digest: "4031337" })
    const markup = renderToStaticMarkup(createElement(RouteError, { error, reset: () => undefined }))

    expect(markup).toContain("Error 500")
    expect(markup).toContain("Try again")
    for (const href of ['href="/"', 'href="/quote"', 'href="/contact"', 'href="mailto:']) expect(markup).toContain(href)
    expect(markup).toContain("4031337")
    expect(markup).not.toContain("private stack detail")
  })
})

