// A/B Lighthouse runner: same flags as web/scripts/check-performance-budgets.mjs, alternating targets.
// Usage: node ab.cjs <runs> <label=url> <label=url> ...
const { spawnSync } = require("node:child_process")
const fs = require("node:fs")
const path = require("node:path")
const lhCli = path.join(__dirname, "lh/node_modules/lighthouse/cli/index.js")
const chrome = "D:/DevCache/ms-playwright/chromium-1228/chrome-win64/chrome.exe"
const runs = Number(process.argv[2])
const targets = process.argv.slice(3).map((t) => t.split("="))
const outDir = path.join(__dirname, "ab-out")
fs.mkdirSync(outDir, { recursive: true })
const results = Object.fromEntries(targets.map(([l]) => [l, []]))
for (let i = 0; i < runs; i++) {
  for (const [label, url] of i % 2 ? [...targets].reverse() : targets) {
    const out = path.join(outDir, `${label}-${i}.json`)
    const r = spawnSync(process.execPath, [lhCli, url, "--quiet", "--output=json", `--output-path=${out}`,
      "--only-categories=performance,accessibility,best-practices,seo", "--preset=desktop",
      "--chrome-flags=--headless=new --no-sandbox --disable-gpu", `--chrome-path=${chrome}`], { encoding: "utf8" })
    if (r.status !== 0) { console.log(label, i, "FAILED", (r.stderr || "").slice(-300)); continue }
    const lhr = JSON.parse(fs.readFileSync(out, "utf8"))
    const a = lhr.audits
    const row = {
      tbt: Math.round(a["total-blocking-time"].numericValue),
      mt: Math.round(a["mainthread-work-breakdown"].numericValue),
      lcp: Math.round(a["largest-contentful-paint"].numericValue),
      bench: Math.round(lhr.environment.benchmarkIndex),
      perf: lhr.categories.performance.score,
    }
    results[label].push(row)
    console.log(label.padEnd(8), i, JSON.stringify(row))
  }
}
const med = (xs) => { const s = [...xs].sort((a, b) => a - b); return s[Math.floor(s.length / 2)] }
for (const [label, rows] of Object.entries(results)) {
  console.log(`${label}: n=${rows.length} TBT median ${med(rows.map((r) => r.tbt))} max ${Math.max(...rows.map((r) => r.tbt))} | MT median ${med(rows.map((r) => r.mt))} | bench median ${med(rows.map((r) => r.bench))}`)
}

